args <- commandArgs(trailingOnly = TRUE)
root <- args[[1L]]
.libPaths(c(file.path(root, ".local", "Rlib"), "/Users/fergushamilton/projects/twosamplemr-fast/.local/Rlib", .libPaths()))
suppressPackageStartupMessages({ library(fastMR); library(TwoSampleMR) })
d <- read.delim(file.path(root, "inst/extdata/il6_crp_primary_100.tsv"), check.names=FALSE, stringsAsFactors=FALSE)
scenarios <- data.frame(name=c("balanced_50x50","one_exposure_250_outcomes","one_outcome_250_exposures","ten_exposures_100_outcomes","hundred_exposures_ten_outcomes"), ne=c(50L,1L,250L,10L,100L), no=c(50L,250L,1L,100L,10L))
make_grid <- function(ne,no) list(exposure_beta=matrix(rep(d$beta.exposure,ne),nrow=ne,byrow=TRUE),outcome_beta=matrix(rep(d$beta.outcome,no),nrow=no,byrow=TRUE),exposure_se=matrix(rep(d$se.exposure,ne),nrow=ne,byrow=TRUE),outcome_se=matrix(rep(d$se.outcome,no),nrow=no,byrow=TRUE))
run_native <- function(g, ne, no, params) { out <- vector("list",ne*no); k <- 0L; for(i in seq_len(ne)) for(j in seq_len(no)) { k <- k+1L; z <- data.frame(SNP=d$SNP,beta.exposure=g$exposure_beta[i,],beta.outcome=g$outcome_beta[j,],se.exposure=g$exposure_se[i,],se.outcome=g$outcome_se[j,],id.exposure="E",id.outcome="O",exposure="E",outcome="O",mr_keep=TRUE); out[[k]] <- suppressMessages(suppressWarnings(TwoSampleMR::mr(z,method_list="mr_simple_median",parameters=params))) }; do.call(rbind,out) }
params <- modifyList(TwoSampleMR::default_parameters(),list(nboot=100L)); rows <- vector("list",nrow(scenarios))
for(k in seq_len(nrow(scenarios))) { s <- scenarios[k,]; g <- make_grid(s$ne,s$no); pairs <- s$ne*s$no; invisible(fast_mr_grid(g$exposure_beta,g$outcome_beta,g$exposure_se,g$outcome_se,methods="simple_median",nboot=0,threads=5)); a <- system.time(fast <- fast_mr_grid(g$exposure_beta,g$outcome_beta,g$exposure_se,g$outcome_se,methods="simple_median",nboot=100,seed=20260805,threads=5))[["elapsed"]]; set.seed(20260805); b <- system.time(native <- run_native(g,s$ne,s$no,params))[["elapsed"]]; beta <- fast$b-native$b; se <- fast$se-native$se; p <- fast$pval-native$pval; rows[[k]] <- data.frame(scenario=s$name,pairs=pairs,fastMR_seconds=a,TwoSampleMR_seconds=b,speedup=b/a,max_abs_beta_difference=max(abs(beta),na.rm=TRUE),median_abs_se_difference=median(abs(se),na.rm=TRUE),max_abs_pval_difference=max(abs(p),na.rm=TRUE)); print(rows[[k]],row.names=FALSE) }
out <- do.call(rbind,rows); write.csv(out,file.path(root,"outputs/native_tsmr_simple_median_benchmark.csv"),row.names=FALSE); md <- c("# Native TwoSampleMR Simple median benchmark","","IL6 fixture: 82 SNPs; nboot=100; fastMR threads=5; seed=20260805.","","| scenario | pairs | fastMR s | TwoSampleMR s | speedup | max beta delta | median SE delta |","|---|---:|---:|---:|---:|---:|---:|"); for(i in seq_len(nrow(out))) md <- c(md,sprintf("| %s | %d | %.3f | %.3f | %.2fx | %.3e | %.3e |",out$scenario[i],out$pairs[i],out$fastMR_seconds[i],out$TwoSampleMR_seconds[i],out$speedup[i],out$max_abs_beta_difference[i],out$median_abs_se_difference[i])); writeLines(md,file.path(root,"outputs/native_tsmr_simple_median_benchmark.md"))
